SELECT r.id,r.id_user,r.id_level,coalesce(u.steam_id::text,'') AS steam_id,l.hash AS level_uid,l.xx_hash AS canonical_hash,r.game_version::text,r.time,coalesce(r.splits,ARRAY[]::real[]) AS splits,coalesce(r.speeds,ARRAY[]::real[]) AS speeds,(SELECT ghost_url FROM public.record_media WHERE id_record=r.id) AS ghost_url FROM public.record r JOIN public.level l ON l.id=r.id_level JOIN public."user" u ON u.id=r.id_user WHERE r.id=$1 AND (NOT $2 OR NOT EXISTS(SELECT 1 FROM zc_private.record_validation v WHERE v.id_record=r.id AND (v.status='fail' OR (v.status='uncertain' AND v.checked_metadata_at>=l.validation_metadata_updated_at))))
